import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom"; // Import for redirection
import { auth } from "../firebase"; // Make sure Firebase is properly set up

import classnames from "classnames";
import { Line, Bar } from "react-chartjs-2";
import {
  Button,
  Card,
  CardHeader,
  CardBody,
  NavItem,
  NavLink,
  Nav,
  Table,
  Container,
  Row,
  Col,
} from "reactstrap";

import { chartOptions, parseOptions, chartExample1, chartExample2 } from "variables/charts.js";
import Header from "components/Headers/Header.js";

const Index = () => {
  const [activeNav, setActiveNav] = useState(1);
  const [chartExample1Data, setChartExample1Data] = useState("data1");
  const [loading, setLoading] = useState(true); // Track authentication check
  const navigate = useNavigate(); // Hook for redirection

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      if (!user) {
        navigate("/auth/login"); // Redirect to login if not authenticated
      } else {
        setLoading(false); // Stop loading once authenticated
      }
    });

    return () => unsubscribe(); // Cleanup function
  }, [navigate]);

  if (loading) {
    return <h1 className="text-center mt-5">Loading...</h1>; // Show a loading screen while checking auth
  }

  return (
    <>
      <Header />
      <Container className="mt--7" fluid>
        <Row>
          <Col className="mb-5 mb-xl-0" xl="8">
            <Card className="bg-gradient-default shadow">
              <CardHeader className="bg-transparent">
                <Row className="align-items-center">
                  <div className="col">
                    <h6 className="text-uppercase text-light ls-1 mb-1">Overview</h6>
                    <h2 className="text-white mb-0">Carbon Emissions Over Time</h2>
                  </div>
                  <div className="col">
                    <Nav className="justify-content-end" pills>
                      <NavItem>
                        <NavLink
                          className={classnames("py-2 px-3", { active: activeNav === 1 })}
                          href="#pablo"
                          onClick={(e) => {
                            e.preventDefault();
                            setActiveNav(1);
                            setChartExample1Data("data1");
                          }}
                        >
                          <span className="d-none d-md-block">Month</span>
                          <span className="d-md-none">M</span>
                        </NavLink>
                      </NavItem>
                      <NavItem>
                        <NavLink
                          className={classnames("py-2 px-3", { active: activeNav === 2 })}
                          href="#pablo"
                          onClick={(e) => {
                            e.preventDefault();
                            setActiveNav(2);
                            setChartExample1Data("data2");
                          }}
                        >
                          <span className="d-none d-md-block">Week</span>
                          <span className="d-md-none">W</span>
                        </NavLink>
                      </NavItem>
                    </Nav>
                  </div>
                </Row>
              </CardHeader>
              <CardBody>
                <div className="chart">
                  <Line data={chartExample1[chartExample1Data]} options={chartExample1.options} />
                </div>
              </CardBody>
            </Card>
          </Col>
          <Col xl="4">
            <Card className="shadow">
              <CardHeader className="bg-transparent">
                <Row className="align-items-center">
                  <div className="col">
                    <h6 className="text-uppercase text-muted ls-1 mb-1">Performance</h6>
                    <h2 className="mb-0">Emission Sources Breakdown</h2>
                  </div>
                </Row>
              </CardHeader>
              <CardBody>
                <div className="chart">
                  <Bar data={chartExample2.data} options={chartExample2.options} />
                </div>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default Index;
